<template>
  <div class="diagram">
    <diagram-toolbar
      class="diagram-toolbar"
      v-if="lf"
      :lf="lf"
      :activeEdges="activeEdges"
      @changeNodeFillColor="$_changeNodeFill"
      @saveGraph="$_saveGraph"
    />
    <div id="myCanvas" class="diagram-main">
      <diagram-sidebar class="diagram-sidebar" @dragInNode="$_dragInNode" />
      <div id="manCancas" class="diagram-container" ref="container">
        <div class="diagram-wrapper">
          <div class="lf-diagram" ref="diagram"></div>
        </div>
      </div>
    </div>
    <!-- 右侧属性面板 -->
    <PropertyPanel
      class="diagram-panel"
      v-if="activeNodes.length>0 || activeEdges.length > 0"
      :onlyEdge="activeNodes.length === 0"
      :elementsStyle="properties"
      @setStyle="$_setStyle"
      @setZIndex="$_setZIndex"
    />
  </div>
</template>

<script>
import LogicFlow from '@logicflow/core'
import { SelectionSelect } from '@logicflow/extension'
import '@logicflow/core/dist/style/index.css'
import '@logicflow/extension/lib/style/index.css'
import DiagramToolbar from './DiagramToolbar.vue'
import DiagramSidebar from './DiagramSidebar.vue'
import PropertyPanel from './PropertyPanel.vue'
import { registerCustomElement } from './node'
import systemFileApi from '@/api/folder'
import localforage from 'localforage'
import { Message } from 'element-ui'
import html2canvas from 'html2canvas'

export default {
  name: 'Diagram',
  data () {
    return {
      queryData: {"nodes":[],"edges":[]},
      fileName: '',
      oldData: null,
      sidebarWidth: 200,
      diagramWidth: 0,
      diagramHeight: 0,
      lf: '',
      filename: '',
      fileId: '',
      activeNodes: [],
      activeEdges: [],
      properties: {},
      createFileForm: {
        id: '',
        type: '',
        desc: '',
        isFolder: 1,
        fileName: '',
        recordType: '',
        parentId: null
      },
      fileDB: null
    }
  },
  created () {
  },
  mounted () {

    let _this = this
    const fileDB = localforage.createInstance({
      name: 'exam-student'
      // 支持config所有配置
      // storeName: 'exam-student', // 仅接受字母，数字和下划线
    })
    this.fileDB = fileDB
    _this.fileDB.setItem('processOnFile', 'some value')

    _this.fileDB.getItem('parentId').then(function(value) {
        // 当离线仓库中的值被载入时，此处代码运行
        console.log('parentId:' + value);
    }).catch(function(err) {
        // 当出错时，此处代码运行
        console.log(err);
    });

    _this.fileDB.getItem('processOnFile').then(function(value) {
        // 当离线仓库中的值被载入时，此处代码运行
        console.log('processOnFile:' + value);
    }).catch(function(err) {
        // 当出错时，此处代码运行
        console.log(err);
    });

    this.fileDB.getItem('createFileName').then(function(value) {

        // 当离线仓库中的值被载入时，此处代码运行
        console.log('createFileName:' + value);
        _this.fileName = value
        if(value == '' || value == null) {
            Message.warning('请选择一个bpms文件！')
            return
        }
        let req = {
           fileName: value,
        }
        systemFileApi.query(req).then(res => {
          console.log('query :' + JSON.stringify(res))

          if(res.code === 1) {

            console.log('fileData :' + res.response.fileData)
            _this.queryData = res.response.fileData
            console.log('_this.queryData :' + _this.queryData)

            console.log('initLogicFlow :' + _this.queryData)
            // 数据
            const data = {"nodes":[{"id":"5166ccb3-bbce-40d1-94c3-49e4ac134a24","type":"circle","x":470,"y":345,"properties":{},"zIndex":1011,"text":{"x":470,"y":345,"value":"圆圈"}},{"id":"9b3f30af-e44b-44e1-a523-8954d4d3db4c","type":"rect","x":235,"y":160,"properties":{},"zIndex":1013,"text":{"x":235,"y":160,"value":"矩阵"}}],"edges":[{"id":"555e4b75-cf69-4b89-8c51-302d4425a5f3","type":"pro-polyline","sourceNodeId":"5166ccb3-bbce-40d1-94c3-49e4ac134a24","targetNodeId":"9b3f30af-e44b-44e1-a523-8954d4d3db4c","startPoint":{"x":470,"y":310},"endPoint":{"x":285,"y":160},"properties":{},"zIndex":1009,"pointsList":[{"x":470,"y":310},{"x":470,"y":160},{"x":285,"y":160}]}]};
            console.log('data:' + JSON.stringify(data))
            console.log('_this.queryData:' + _this.queryData)
            _this.initLogicFlow(JSON.parse(_this.queryData))
          }else{
            Message.warning('文件不存在，请确认清楚！')
          }
        })

    }).catch(function(err) {
        // 当出错时，此处代码运行
        console.log(err);
    });

    if (window.location.search) {
      console.log(window.location.search)
      const query = window.location.search.substring(1).split('&').reduce((map, kv) => {
        const [key, value] = kv.split('=')
        map[key] = value
        return map
      }, {})
      //this.filename = query.filename
      //const d = window.sessionStorage.getItem(this.filename)
      //console.log(d)
      this.fileId = query.fileId

      if (this.fileId) {
        this.createFileForm.fileId = this.fileId
        systemFileApi.saveOrUpdateJdkFolderFile(this.createFileForm).then(res => {
          console.log('saveOrUpdateJdkFolderFile:' + JSON.stringify(res))
        })
      }
    }

    _this.initLogicFlow(null)

  },
  methods: {
    initLogicFlow (data) {
      // 引入框选插件
      LogicFlow.use(SelectionSelect)
      const lf = new LogicFlow({
        container: this.$refs.diagram,
        overlapMode: 1,
        autoWrap: true,
        metaKeyMultipleSelected: true,
        keyboard: {
          enabled: true
        },
        grid: {
          visible: false,
          size: 5
        },
        background: {
          backgroundImage: 'url("data:image/svg+xml;base64,")',
          backgroundRepeat: 'repeat'
        }
      })
      lf.setTheme(
        {
          baseEdge: { strokeWidth: 1 },
          baseNode: { strokeWidth: 1 },
          nodeText: { overflowMode: 'autoWrap', lineHeight: 1.5 },
          edgeText: { overflowMode: 'autoWrap', lineHeight: 1.5 }
        }
      )
      // 注册自定义元素
      registerCustomElement(lf)
      lf.setDefaultEdgeType('pro-polyline')

      lf.render(data)
      this.lf = lf
      let imgData = null
      this.lf.on('selection:selected,node:click,blank:click,edge:click', () => {
        this.$nextTick(() => {


          // 选择你想要转换成图片的 DOM 元素
          const element = document.querySelector("#manCancas")
          html2canvas(element).then(canvas => {
            // canvas.toDataURL() 可以获取图片的 base64 编码
            const dataUrl = canvas.toDataURL('image/png')
            // 你可以将 dataUrl 设置为一个 img 标签的 src 属性，或者下载图片等
            //console.log('img base64:' + dataUrl)
            //const img = document.querySelector("#imgs")
            //img.src = dataUrl
            imgData = dataUrl
          })

          if(this.fileName == '' || this.fileName == null) {
            Message.warning('文件不存在，请确认清楚！')
            return
          }

          const { nodes, edges } = this.lf.getSelectElements()
          this.$set(this, 'activeNodes', nodes)
          this.activeNodes = nodes
          this.activeEdges = edges
          this.$_getProperty()

          console.log('data print')
          const newData = JSON.stringify(this.lf.getGraphData())
          let result = newData.localeCompare(this.oldData)
          this.oldData = newData
          if(result != 0) {
            console.log('update file')

            let req = {
                fileName: this.fileName,
                content: newData,
                imgData: imgData,
            }
            systemFileApi.saveOrUpdateJdkFolderFile(req).then(res => {
              console.log('saveOrUpdateJdkFolderFile:' + JSON.stringify(res))
            })

          }
          console.log('content:' + newData)
          console.log('result:' + result)
        })
      })
    },
    // 获取可以进行设置的属性
    $_getProperty () {
      let properties = {}
      const { nodes, edges } = this.lf.getSelectElements()
      nodes.forEach(node => {
        properties = { ...properties, ...node.properties }
      })
      edges.forEach(edge => {
        properties = { ...properties, ...edge.properties }
      })
      this.properties = properties
      return properties
    },
    $_dragInNode (type) {
      this.lf.dnd.startDrag({
        type
      })
    },
    $_changeNodeFill (color) {
      const { nodes } = this.lf.graphModel.getSelectElements()
      nodes.forEach(({ id }) => {
        this.lf.setProperties(id, {
          fill: color
        })
      })
    },
    $_setStyle (item) {
      this.activeNodes.forEach(({ id }) => {
        this.lf.setProperties(id, item)
      })
      this.activeEdges.forEach(({ id }) => {
        this.lf.setProperties(id, item)
      })
      this.$_getProperty()
    },
    $_setZIndex (type) {
      this.activeNodes.forEach(({ id }) => {
        this.lf.setElementZIndex(id, type)
      })
      this.activeEdges.forEach(({ id }) => {
        this.lf.setElementZIndex(id, type)
      })
    },
    $_saveGraph () {
      const data = this.lf.getGraphData()
      this.download(this.filename, JSON.stringify(data))
    },
    download (filename, text) {
      window.sessionStorage.setItem(filename, text)
      const element = document.createElement('a')
      element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(text))
      element.setAttribute('download', filename)
      element.style.display = 'none'
      document.body.appendChild(element)
      element.click()
      document.body.removeChild(element)
    }
  },
  components: {
    DiagramToolbar,
    DiagramSidebar,
    PropertyPanel
  }
}
</script>

<style scoped>

.diagram {
  width: 100%;
  height: 100%;
}
.diagram * {
  box-sizing: border-box;
}
.diagram-toolbar {
  position: absolute;
  top: 0;
  left: 200px;
  height: 40px;
  width: 310px;
  display: flex;
  align-items: center;
  border-bottom: 1px solid #e5e5e5;
  z-index: 10;
  background: #e5e5e5;
}
.diagram-main {
  display: flex;
  width: 100%;
  height: 100%;
}
.diagram-sidebar {
  width: 185px;
  height: calc(100% - 40px);
  border-right: 1px solid #dadce0;
  padding: 10px;
}
.diagram-panel {
  width: 300px;
  background: #fff;
  height: calc(100% - 40px);
  position: absolute;
  right: 0px;
  top: 40px;
  border-left: 1px solid #dadce0;
}
.diagram-container {
  flex: 1;
}
/* 由于背景图和gird不对齐，需要css处理一下 */
.diagram /deep/ .lf-background {
  left: -9px;
}
.diagram-wrapper {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
}
.lf-diagram {
  box-shadow: 0px 0px 4px #838284;
  width: 100%;
  height: 100%;
}
::-webkit-scrollbar {
  width: 9px;
  height: 9px;
  background: white;
  border-left: 1px solid #e8e8e8;
}
::-webkit-scrollbar-thumb {
  border-width: 1px;
  border-style: solid;
  border-color: #fff;
  border-radius: 6px;
  background: #c9c9c9;
}
::-webkit-scrollbar-thumb:hover {
  background: #b5b5b5;
}
</style>